import React from 'react';
import { User } from '../pages/Users';

interface Column {
  label: string;
  key: keyof User;
  action 
}

interface Props {
  data: User[];
  columns: Column[];
  onSort: (key: keyof User) => void;
}

export const UserTable: React.FC<Props> = ({
  data,
  columns,
  onSort,
}) => {
  return (
    <div
      style={{
        width: '100%',
        overflowX: 'auto',
        background: '#FFFFFF',
        borderRadius: 12,
        border: '1px solid #E2E8F0',
      }}
    >
      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          minWidth: 700,
        }}
      >
        <thead
          style={{
            background: '#F8FAFC',
          }}
        >
          <tr>
            {columns.map((column) => (
              <th
                key={String(column.key)}
                onClick={() => onSort(column.key)}
                style={{
                  padding: '16px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  borderBottom: '1px solid #E2E8F0',
                  color: '#334155',
                  fontWeight: 600,
                  fontSize: 14,
                }}
              >
                {column.label}
              </th>
            ))}
          </tr>
        </thead>

        <tbody>
          {data.map((user) => (
            <tr
              key={user.id}
              style={{
                transition: 'background 0.2s',
              }}
            >
              <td
                style={{
                  padding: '16px',
                  borderBottom: '1px solid #F1F5F9',
                }}
              >
                {user.name}
              </td>

              <td
                style={{
                  padding: '16px',
                  borderBottom: '1px solid #F1F5F9',
                }}
              >
                {user.email}
              </td>

              <td
                style={{
                  padding: '16px',
                  borderBottom: '1px solid #F1F5F9',
                }}
              >
                <span
                  style={{
                    padding: '6px 10px',
                    borderRadius: 999,
                    background:
                      user.role === 'Admin'
                        ? '#DCFCE7'
                        : '#DBEAFE',
                    color:
                      user.role === 'Admin'
                        ? '#166534'
                        : '#1E40AF',
                    fontSize: 12,
                    fontWeight: 600,
                  }}
                >
                  {user.role}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {data.length === 0 && (
        <div
          style={{
            padding: 32,
            textAlign: 'center',
            color: '#64748B',
          }}
        >
          No users found
        </div>
      )}
    </div>
  );
};
